const SETS: Record<string, readonly { x: number; y: number; amount: number }[]> = {
  ...STROKE_FIXTURES,
  IDEAL_FIXTURE: buildIdealSauceFixture(),
  IDEAL_MARGHERITA: IDEAL_MARGHERITA_SAUCE_FIXTURE,
  EMPTY: [],
};

describe("scoring-side Sauce numbers are unchanged by the Slice 1 display rewrite (Issue #475)", () => {
  const reference = getReferencePizza("margherita")?.sauce;
  it("has the margherita reference the pins were generated against", () => {
    expect(reference).toBeTruthy();
  });

  it.each(Object.keys(MAIN_6B86798))("%s: computeSauceMetrics / tiers / live message / Scoring 2.0 Sauce match main exactly", (name) => {
    const expected = MAIN_6B86798[name as keyof typeof MAIN_6B86798];
    const metrics = computeSauceMetrics(SETS[name]);
    expect(metrics).toEqual(expected.metrics);
    expect(evaluateSauceForPlayer(metrics, reference!)).toEqual(expected.evaluation);
    expect(deriveSauceLiveMessage(metrics, reference!)).toBe(expected.live);
    expect(scoreSauceComponentV2(metrics, reference!)).toEqual(expected.v2);
  });
});
